def tropical_partition(E):
    """Tropical partition function: Z_trop = min_i E(i)."""
    import numpy as np
    return float(np.min(E))

def tropical_channel_output(E, K):
    """Tropical channel: Ch(b) = min_a [E(a) + K(a,b)]."""
    import numpy as np
    return np.min(E[:, None] + K, axis=0)
